/* global Excel, Office */

let updateInterval; // Zamanlayıcıyı saklamak için

Office.onReady((info) => {
  if (info.host === Office.HostType.Excel) {
    // Manuel çekme butonu
    document.getElementById("run-button").onclick = verileriCek;

    // Otomatik güncelleme kutucuğu
    const autoUpdateCb = document.getElementById("auto-update-cb");
    autoUpdateCb.onchange = function() {
        toggleAutoUpdate(this.checked);
    };
  }
});

async function toggleAutoUpdate(isEnabled) {
    const timerText = document.getElementById("timer-text");
    
    if (isEnabled) {
        timerText.innerText = "Aktif: 5 dakikada bir güncelleniyor...";
        timerText.style.color = "green";
        
        // 5 dakika = 300,000 milisaniye
        updateInterval = setInterval(verileriCek, 300000); 
        
        // Kutucuk işaretlenir işaretlenmez ilk veriyi hemen çek
        await verileriCek();
    } else {
        timerText.innerText = "Kapalı (İşaretlendiğinde 5 dk'da bir yeniler)";
        timerText.style.color = "#888";
        
        // Zamanlayıcıyı durdur
        if (updateInterval) {
            clearInterval(updateInterval);
        }
    }
}

async function verileriCek() {
    const status = document.getElementById("status");
    const targetSheetName = "GoogleVerileri";
    const apiURL = "https://script.google.com/macros/s/AKfycbxULPYNOZv_ZrY81RL-YJ14LJcd5MMPUPU6Esc7eQer9w3s16m1hh7h6jUk13_zy1Y/exec";

    status.innerText = "Durum: Senkronize ediliyor...";
    status.style.color = "blue";

    try {
        const response = await fetch(apiURL, { method: 'GET', redirect: 'follow' });
        const data = await response.json();

        await Excel.run(async (context) => {
            const sheets = context.workbook.worksheets;
            let sheet = sheets.getItemOrNullObject(targetSheetName);
            sheet.load("isNullObject");
            await context.sync();

            if (sheet.isNullObject) {
                sheet = sheets.add(targetSheetName);
            }

            // İçeriği temizle
            sheet.getUsedRange().clear(Excel.ClearApplyTo.contents);

            // Veri boyutuna göre aralık belirle
            const rowCount = data.length;
            const columnCount = data[0].length;
            const range = sheet.getRangeByIndexes(0, 0, rowCount, columnCount);
            
            range.values = data;
            range.format.autofitColumns();

            await context.sync();
            status.innerText = "Durum: Son Güncelleme " + new Date().toLocaleTimeString();
            status.style.color = "green";
        });

    } catch (e) {
        console.error(e);
        status.innerText = "Durum: Hata Oluştu!";
        status.style.color = "red";
    }
}